"""Aggregate projection adapted from the 05/10 full study builder.

Only frozen notebook_runs are read by the generated SQL. Projection expressions
are retained from the historical reproducible source; current references,
provenance, contract and definition ordering are supplied by the caller.
Original source SHA256: 633600daad1dc998a9aec75200dc158ed9799662bb07db9c9984ff20f3dde811
"""
import json

def source_date(run):
    value=str(run['started_at'])[:10]
    if len(value)!=10 or value[4]!='-' or value[7]!='-':raise ValueError('started_at must begin with ISO date')
    return value[8:10]+'/'+value[5:7]+'/'+value[:4]

def provenance(run):
    return {'celula':run['cell_id'],'revisao':run['cell_version'],'execucao':run['id'],'coletado_em':run['started_at']}

def source_label(run):
    return f"Notebook · célula {run['cell_id']} rev{run['cell_version']} · congelamento {run['id']} · coleta {source_date(run)}"

def build_projection(source_runs, baseline, baseline_run):
    Q=lambda x:"'"+str(x).replace("'","''")+"'"
    runs={}
    ct=[]
    def load(name,alias,payload=True):
     r=source_runs[name];runs[alias]=r
     ct.append(f"{alias} AS (SELECT result->'rows' AS rows,result->'rows'->0->'payload' AS p FROM estudo.notebook_runs WHERE id={r['id']} AND cell_id={r['cell_id']} AND cell_version={r['cell_version']} AND frozen AND status='ok' AND NOT truncated)")
     return alias
    for y in [2023,2024,2025]:load(f'geracoes-{y}-anual',f'age{y}')
    load('geracoes-2026-q3','age2026');load('alfa-z-variacoes','az')
    for name,alias in [('geral-2026-q3','g'),('geral-2025-q3','b'),('mensais-provas-q3','calendar'),('performance-cna-q3','perf'),('maratonas-q3','m'),('cobertura-q3','cov'),('corte14-2025','a14p'),('corte14-2026-q3','a14'),('cidades-q3','cities'),('capital-interior-q3','capital'),('perfil-q3','profile'),('activites-q3-agregadas','sport'),('mapeamento-q3','mapping'),('cadastro-maratonas-q3','registry'),('precos-resumo-q3','price'),('precos-geral-q3','general'),('porte-q3','size'),('edicoes-calendario-2026','editions')]:load(name,alias)
    ct+= ["medalvalues AS(SELECT v->>'id_evento' AS id_evento,v->>'nome_evento' AS nome,v->>'data_final' AS data,kv.key AS criterio,CASE WHEN kv.key LIKE 'sub%' THEN -(kv.value #>> '{}')::numeric ELSE extract(epoch FROM (kv.value #>> '{}')::time) END AS valor FROM m,jsonb_array_elements(p->'top10')v,jsonb_each(v)kv WHERE v->>'id_evento'<>'34529' AND kv.key IN('sub4','sub3','sub2h30','tempo_menor','tempo_medio','tempo_mediano') UNION ALL SELECT v->>'id_evento',v->>'nome_evento',v->>'data_final',v->>'grupo',extract(epoch FROM(v->>'tempo_medio')::time) FROM m,jsonb_array_elements(p->'grupos')v WHERE v->>'id_evento'<>'34529'),medalranks AS(SELECT *,rank() OVER(PARTITION BY criterio ORDER BY valor) AS posicao FROM medalvalues)","months AS(SELECT CASE WHEN v->>'ano'='2025' THEN 2025 ELSE 2026 END AS ano,(v->>'mes')::int AS mes,(v->>'concluintes_estudo')::bigint AS n,(v->>'provas_cadastradas')::bigint AS cadastradas,(v->>'provas_com_resultado_coletado')::bigint AS coletadas,(v->>'provas_com_concluintes_elegiveis')::bigint AS elegiveis FROM calendar CROSS JOIN LATERAL jsonb_array_elements(p->'mensais')v)",
    "pairmonths AS(SELECT a.mes,a.n AS n25,z.n AS n26,a.cadastradas AS c25,z.cadastradas AS c26,a.coletadas AS k25,z.coletadas AS k26,a.elegiveis AS e25,z.elegiveis AS e26 FROM months a JOIN months z USING(mes) WHERE a.ano=2025 AND z.ano=2026)",
    "monthlabels AS(SELECT column1 AS mes,column2 AS rotulo FROM(VALUES(1,'Jan'),(2,'Fev'),(3,'Mar'),(4,'Abr'),(5,'Mai'),(6,'Jun'),(7,'Jul'),(8,'Ago'),(9,'Set'))t)"]
    # Values are SQL expressions over immutable frozen rows; no operational tables in output.
    for year,previous,contract in [(2026,baseline_run['id'],17)]:
     old=baseline; defs={s['id']:s for s in old['series']};parts=[]
     def add(s,cat,val,n,d,alias,from_,where='',unit='percentual',dec=1,note=None,order='0'):
      if isinstance(s,str) and s.startswith("'"):
       if s.strip("'") not in defs:defs[s.strip("'")]={'id':s.strip("'"),'unidade':unit,'casas_decimais':dec,'pagina_pdf':None,'status':'notebook_em_conciliacao','valores':[]}
      r=runs[alias];src=Q(f"Notebook · célula {r['cell_id']} rev{r['cell_version']} · congelamento {r['id']} · coleta {source_date(r)}")
      note=note or ('Idade em31/12. Nascimento plausível prioritário; sem nascimento, faixa finita14+ cruzando somente duas gerações atribuída pela idade central (menor central no empate), uma vez. Sem idade, abertas cruzando grupos e faixas amplas permanecem desconhecidas. Alfa>=2010;Z1997–2009;Millennials1981–1996;X1965–1980;Boomers1946–1964. Aproximações identificadas.' if alias.startswith('age') else f'Fonte congelada própria; {year}'+(' anual.' if year==2025 else ' de01/01 a30/09, primeiro ao terceiro trimestre.'))
      parts.append(f"SELECT {s} AS serie,{cat} AS categoria,({val})::text AS valor,to_jsonb({n}) AS n,to_jsonb({d}) AS d,{src} AS fonte,{Q(note)} AS nota,({order})::integer AS ordem FROM {from_}"+(' WHERE '+where if where else ''))
     for y in ([2023,2024,2025] if year==2025 else [2026]):
      alias=f'age{y}';fr=f"{alias} CROSS JOIN LATERAL jsonb_array_elements(rows)v"
      add(f"'geracoes_{y}_'||(v->>'sexo')","v->>'categoria'","v->>'percentual'","v->'total'","v->'denominador'",alias,fr,"v->>'bloco'='geracao'",order="v->>'ordem'")
      add(f"'geracao_criterio_{y}_'||(v->>'sexo')","v->>'categoria'","v->>'percentual'","v->'total'","v->'denominador'",alias,fr,"v->>'bloco'='criterio'")
      # dynamic new IDs handled by SQL fallback definition.
      if y==year:
       for block,expr,cat in [('idade',"'idades_'||(v->>'sexo')","v->>'categoria'"),('origem',"'qualidade_idades_'||(v->>'sexo')","v->>'categoria'"),('geracao_na_distancia',"'geracao_dentro_distancia_'||(v->>'distancia')","v->>'categoria'"),('distancia_na_geracao',"'distancia_dentro_geracao_'||(v->>'categoria')","v->>'distancia'")]:
        add(expr,cat,"v->>'percentual'","v->'total'","v->'denominador'",alias,fr,f"v->>'bloco'={Q(block)}",order="v->>'ordem'")
     add("'alfa_z_variacao_pp_'||(v->>'sexo')","'Versus '||(v->>'ano_base')","v->>'diferenca_pp'","v->'jovens'","v->'total'",'az',"az CROSS JOIN LATERAL jsonb_array_elements(rows)v",f"v->>'ano'='{year}'",unit='numero',dec=2,note='Diferença em pontos percentuais: (Alfa+Z14+ / todas as participações do gênero no ano) menos a mesma participação no ano base. Inclui desconhecidos e menores14 no denominador; não mede atletas únicos, nem crescimento de quantidade.2025 compara anos completos;2026 compara janeiro–setembro nos dois anos.',order="v->>'ano_base'")
     if year==2026:
      # General distributions, preserving unknowns and original unit labels.
      for indicador,expr in [('sexo',"'sexo_2026'"),('regiao',"'regioes_2026'"),('uf',"'ufs'"),('mes',"'meses'"),('trimestre',"'trimestres'"),('sexo_por_regiao',"'sexo_por_regiao_'||(v->>'segmento')"),('distancia_faixas',"'distancias_faixas'"),('distancia_floor',"'distancias_detalhe'"),('sexo_dentro_distancia',"'sexo_dentro_distancia_'||(v->>'segmento')")]:
       if indicador=='distancia_floor':continue
       regmap=lambda col:"CASE "+col+" WHEN 'N' THEN 'Norte' WHEN 'NE' THEN 'Nordeste' WHEN 'CO' THEN 'Centro-Oeste' WHEN 'SE' THEN 'Sudeste' WHEN 'S' THEN 'Sul' ELSE "+col+" END"
       if indicador=='sexo_por_regiao':expr="'sexo_por_regiao_'||"+regmap("v->>'segmento'")
       cat=regmap("v->>'categoria'") if indicador=='regiao' else "(SELECT rotulo FROM monthlabels WHERE mes=(v->>'categoria')::int)" if indicador=='mes' else "(v->>'categoria')||' km'" if indicador=='distancia_floor' else "v->>'categoria'"
       add(expr,cat,"v->>'percentual'","v->'total'","v->'denominador'",'g',"g CROSS JOIN LATERAL jsonb_array_elements(p->'recortes')v",f"v->>'indicador'={Q(indicador)}",note='BR pela data final de01/01 a30/09; status0,homologado,concluinte; todas as idades/modalidades nos totais; distâncias exigem rua e percurso positivo. Cada linha é uma participação. Categorias desconhecidas permanecem no denominador.')
      for sex,name in [('F','feminino'),('M','masculino')]:
       add(Q('regioes_'+name+'_rotulos_visiveis'),regmap("v->>'segmento'"),"(v->>'total')::numeric*100.0/(SELECT sum((z->>'total')::numeric) FROM jsonb_array_elements(g.p->'recortes')z WHERE z->>'indicador'='sexo_por_regiao' AND z->>'categoria'=v->>'categoria')","v->'total'","(SELECT sum((z->>'total')::numeric) FROM jsonb_array_elements(g.p->'recortes')z WHERE z->>'indicador'='sexo_por_regiao' AND z->>'categoria'=v->>'categoria')",'g',"g,jsonb_array_elements(p->'recortes')v",f"v->>'indicador'='sexo_por_regiao' AND v->>'categoria'='{sex}'",note='Percentual de participações do gênero entre todas as regiões, incluindo não informada;01/01–30/09. Denominador nacional do gênero, distinto de composição dentro da região.')
      add("'eventos_com_5km'","'5 km'","100.0*count(*) FILTER(WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(v->'percursos')d WHERE(d->>'percurso')::numeric=5 AND(d->>'concluintes')::bigint>0))/nullif(count(*),0)","count(*) FILTER(WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(v->'percursos')d WHERE(d->>'percurso')::numeric=5 AND(d->>'concluintes')::bigint>0))","count(*)",'editions',"editions,jsonb_array_elements(p->'eventos')v","v->>'tipo_corrida'='rua' AND(v->>'na_janela')::boolean AND(v->>'concluintes')::bigint>0",note='Provas de ruaBR com conclusão registrada01/01–30/09; numerador com ao menos uma conclusão de percurso exatamente5km. Cada id_evento uma vez; não mede inscrições vendidas.')
      # Invert gender x distance using exactly frozen cell counts.
      add("'distancia_dentro_sexo_'||(v->>'categoria')","v->>'segmento'","100.0*(v->>'total')::numeric/nullif((SELECT sum((z->>'total')::numeric) FROM jsonb_array_elements(g.p->'recortes')z WHERE z->>'indicador'='sexo_dentro_distancia' AND z->>'categoria'=v->>'categoria'),0)","v->'total'","(SELECT sum((z->>'total')::numeric) FROM jsonb_array_elements(g.p->'recortes')z WHERE z->>'indicador'='sexo_dentro_distancia' AND z->>'categoria'=v->>'categoria')",'g',"g CROSS JOIN LATERAL jsonb_array_elements(p->'recortes')v","v->>'indicador'='sexo_dentro_distancia' AND v->>'categoria' IN('F','M')")
      # UF top uses frozen counts, leaving full UF table separately.
      ct2=["distcounts AS(SELECT v,(v->>'total')::bigint AS total FROM g,jsonb_array_elements(p->'recortes')v WHERE v->>'indicador'='distancia_floor'),distorder AS(SELECT *,row_number() OVER(ORDER BY total DESC,v->>'categoria') AS ordem FROM distcounts)","ufcounts AS(SELECT v,(v->>'total')::bigint AS total FROM g CROSS JOIN LATERAL jsonb_array_elements(p->'recortes')v WHERE v->>'indicador'='uf'),ufrank AS(SELECT v,row_number() OVER(ORDER BY total DESC,v->>'categoria') AS ordem FROM ufcounts)"]
      add("'distancias_detalhe'","CASE WHEN ordem<=10 THEN(v->>'categoria')||' km' ELSE 'Outras' END","sum(total)*100.0/max((v->>'denominador')::numeric)","sum(total)","max((v->>'denominador')::numeric)",'g','distorder',order='min(CASE WHEN ordem<=10 THEN ordem ELSE 11 END)',note='Dez distâncias mais frequentes pela parte inteira; demais agrupadas. BR/rua com percurso positivo e conclusão; até30/09, uma participação uma vez.')
      parts[-1]+=" GROUP BY CASE WHEN ordem<=10 THEN(v->>'categoria')||' km' ELSE 'Outras' END"
      add("'ufs_top_grafico'","CASE WHEN ordem<=9 THEN v->>'categoria' ELSE 'Outras' END","sum((v->>'total')::numeric)*100.0/max((v->>'denominador')::numeric)","sum((v->>'total')::bigint)","max((v->>'denominador')::bigint)",'g','ufrank',order='min(CASE WHEN ordem<=9 THEN ordem ELSE 10 END)',note='Nove UFs com maior volume e demais agrupadas; tabela completa e desconhecidos preservados.')
      parts[-1]+=" GROUP BY CASE WHEN ordem<=9 THEN v->>'categoria' ELSE 'Outras' END"
      for alias,block,expr,cat in [('cities','cidades',"'cidades'","(v->'dados'->>'rotulo')||' · '||(v->'dados'->>'uf')"),('capital','geografia',"'capital_interior_'||CASE v->'dados'->>'regiao' WHEN 'N' THEN 'Norte' WHEN 'NE' THEN 'Nordeste' WHEN 'CO' THEN 'Centro-Oeste' WHEN 'SE' THEN 'Sudeste' WHEN 'S' THEN 'Sul' ELSE v->'dados'->>'regiao' END","v->'dados'->>'tipo'")]:
       add(expr,cat,"v->'dados'->>'percentual'","v->'dados'->'total'","v->'dados'->'denominador'",alias,f"{alias} CROSS JOIN LATERAL jsonb_array_elements(rows)v",f"v->>'bloco'='{block}' AND v->'dados'->>'ano'='2026'",note='Cidade/UF normalizadas e código validado; cada participação uma vez. Ausências e inconsistências conservadas no denominador; rua para capital/interior.',order="coalesce(v->'dados'->>'ordem','0')")
      for ind,expr in [('performance',"'performance_'||(v->>'distancia')||'_'||(v->>'segmento')"),('cna',"'cna_'||(v->>'distancia')")]:
       fr="perf CROSS JOIN LATERAL jsonb_array_elements(p->'recortes')v JOIN oldseries os ON os.x->>'id'="+expr+" CROSS JOIN LATERAL jsonb_array_elements(os.x->'valores') WITH ORDINALITY AS t"
       add(expr,"t.value->>'rotulo'","v->>'percentual'","v->'total'","v->'denominador'",'perf',fr,f"v->>'indicador'='{ind}' AND (v->>'faixa_ordem')::int=t.ordinality"+(" AND v->>'segmento'='geral'" if ind=='cna' else ''),note='Limites recuperados das queries existentes, na matriz SQL da fonte. Tempo positivo. Performance exige rua; CNA exige PCD=false e ranking elegível, distâncias próprias. Mesmos filtros revisados anteriormente, coleta até30/09.',order='t.ordinality')
      # Normalized current profile and registered sports.
      add("'perfil_cards'","CASE WHEN v->>'regra'='peso_20_300' THEN 'Peso médio' ELSE v->>'categoria' END","v->>'valor'","CASE WHEN v->>'unidade'='percentual' THEN v->'numerador' ELSE v->'denominador' END","v->'denominador'",'profile',"profile CROSS JOIN LATERAL jsonb_array_elements(rows)v","v->>'ano'='2026' AND v->>'regra'<>'peso_positivo'",note='Todos os usuários cadastrados até30/09. Atributos atuais, bases por indicador; peso20–300kg inclusive. Não reconstitui atributos históricos nem mede crescimento.',order="v->>'ordem'")
      mapping="sportmap"
      ct2.append("sportmap AS(SELECT column1 AS tipo,column2 AS categoria FROM(VALUES('WeightTraining','Fortalecimento'),('Walk','Caminhada'),('Workout','Treino livre'),('Ride','Pedal'),('Swim','Natação'),('Yoga','Yoga'),('VirtualRide','Rolo'),('Hike','Trilha'),('Elliptical','Elíptico'),('Crossfit','Crossfit'),('StairStepper','Stepper'))t)")
      add("'outros_esportes'","sportmap.categoria","v->>'percentual'","v->'total'","v->'denominador'",'sport',"sport CROSS JOIN LATERAL jsonb_array_elements(rows)v JOIN "+mapping+" ON v->>'type'=sportmap.tipo",note='Atividades de01/01 a30/09; soma de nove meses congelados, exclui indicação aspect_type=delete; denominador todos os tipos não nulos, inclusive Run. Não são atletas únicos.')
      # Coverage / 14+ audit / deduplicated mapping.
      for id,field,unit in [('coleta_eventos_cadastrados','cadastradas','provas'),('coleta_eventos_coletados','coletadas','provas'),('coleta_eventos_concluintes','com_concluintes','provas'),('coleta_cobertura_cadastral','coleta_pct','percentual')]:
       add(Q(id),"(v->>'escopo')||' · '||(v->>'universo')",f"v->>'{field}'",f"v->'{('coletadas' if unit=='percentual' else field)}'","v->'cadastradas'",'cov',"cov CROSS JOIN LATERAL jsonb_array_elements(p->'cobertura')v","v->>'fim_exclusivo' LIKE '%-10-01'",unit=unit)
      for id,field,pct in [('qualidade_conclusao','conclusao',False),('qualidade_corte14','corte14',False),('qualidade_corte14_pct','corte14',True)]:
       add(Q(id),f"v->>'{field}'","sum((v->>'n')::bigint)"+("*100.0/(SELECT sum((a->>'n')::bigint) FROM a14,jsonb_array_elements(p->'idades')a WHERE a->>'universo'='Todas as modalidades' AND a->>'conclusao'='Conclusão registrada')" if pct else ''),"sum((v->>'n')::bigint)","(SELECT sum((a->>'n')::bigint) FROM a14,jsonb_array_elements(p->'idades')a WHERE a->>'universo'='Todas as modalidades'"+(" AND a->>'conclusao'='Conclusão registrada'" if field=='corte14' else '')+")",'a14',"a14 CROSS JOIN LATERAL jsonb_array_elements(p->'idades')v","v->>'universo'='Todas as modalidades'"+(" AND v->>'conclusao'='Conclusão registrada'" if field=='corte14' else ''),unit='percentual' if pct else 'participacoes',dec=1 if pct else 0)
       parts[-1]+=f" GROUP BY v->>'{field}'"
      add("'mapeamento_real'","v->>'categoria'","v->>'valor'","v->'contagem'","v->'denominador'",'mapping',"mapping CROSS JOIN LATERAL jsonb_array_elements(p->'linhas')v","v->>'ano'='2026'",note='Cada evento ativoBR com UF reconhecida uma vez. Mapeadas=resultado bruto ou link ou situação conhecida. Não estima conclusão/completude; fórmula deduplicada SQL, ausência de evidência é parcela complementar.')
      add("'destaques'","'Concluintes'","p->>'resultados'","p->'resultados'","p->'resultados'",'g','g',unit='participacoes',dec=0)
      add("'destaques'","'Eventos'","(SELECT sum(cadastradas) FROM months WHERE ano=2026)","(SELECT sum(cadastradas) FROM months WHERE ano=2026)","(SELECT sum(cadastradas) FROM months WHERE ano=2026)",'calendar','calendar',unit='provas',dec=0)
      add("'destaques'","'Resultados mapeados'","v->>'valor'","v->'contagem'","v->'denominador'",'mapping',"mapping,jsonb_array_elements(p->'linhas')v","v->>'ano'='2026' AND v->>'categoria'='Provas mapeadas'")
      # First three quarters, completed date window, not completed imports.
      for y in [2025,2026]:
       for id,field,unit in [(f'comparativo_mensal_{y}','n','participacoes'),(f'comparativo_provas_cadastradas_{y}','cadastradas','provas'),(f'comparativo_provas_coletadas_{y}','coletadas','provas')]:
        add(Q(id),'rotulo',field,field,'NULL::bigint','calendar','months JOIN monthlabels USING(mes)',f'ano={y}',unit=unit,dec=0,order='mes')
       for cat,field in [('Provas cadastradas','cadastradas'),('Provas com resultado coletado','coletadas')]:
        add(Q(f'comparativo_provas_resumo_{y}'),Q(cat),f'sum({field})',f'sum({field})','NULL::bigint','calendar','months',f'ano={y}',unit='provas',dec=0)
      add("'estacoes'","CASE WHEN mes<=2 THEN 'Verão' WHEN mes<=5 THEN 'Outono' WHEN mes<=8 THEN 'Inverno' ELSE 'Primavera' END","sum(n)*100.0/(SELECT sum(n) FROM months WHERE ano=2026)",'sum(n)','(SELECT sum(n) FROM months WHERE ano=2026)','calendar','months','ano=2026',note='Meses inteiros: verão dez–fev,outono mar–mai,inverno jun–ago,primavera set–nov.2026Jan–Set contém apenas jan/fev e setembro nas estações incompletas; não contabiliza outubro–dezembro como zero.')
      parts[-1]+=" GROUP BY CASE WHEN mes<=2 THEN 'Verão' WHEN mes<=5 THEN 'Outono' WHEN mes<=8 THEN 'Inverno' ELSE 'Primavera' END"
      # Marathon conventional population; Floripa values remain NULL pending recapture.
      for id,field,unit in [('concluintes','concluintes','participacoes'),('feminino','feminino','percentual'),('masculino','masculino','percentual'),('tempo_menor','tempo_menor','duracao_hh_mm_ss'),('tempo_medio','tempo_medio','duracao_hh_mm_ss'),('tempo_mediano','tempo_mediano','duracao_hh_mm_ss')]+[(f'{x}_{u}',x,'percentual' if u=='percentual' else 'participacoes') for x in ['sub4','sub3','sub2h30'] for u in ['contagem','percentual']]:
       val=f"v->>'{field}'" if unit!='percentual' else f"100.0*(v->>'{field}')::numeric/nullif((v->>'concluintes')::numeric,0)"
       if field not in ['concluintes','feminino','masculino']:val=f"CASE WHEN v->>'id_evento'='34529' THEN NULL ELSE ({val})::text END"
       add(Q('maratonas_'+id),"(v->>'nome_evento')||' · '||to_char((v->>'data_final')::date,'DD/MM')",val,(f"CASE WHEN v->>'id_evento'='34529' THEN NULL ELSE v->'{field}' END" if field in ['sub4','sub3','sub2h30'] else f"v->'{field}'") if unit!='duracao_hh_mm_ss' else 'NULL::bigint',"v->'concluintes'",'m',"m CROSS JOIN LATERAL jsonb_array_elements(p->'top10')v",unit=unit,dec=0 if unit=='participacoes' else 1,note='Regra convencional revisada:42–42,2km/rua/BR/ranking/PCD=false/status0/homologado/concluinte/tempo positivo/exclusão explícita de modalidades especiais. Floripa mantém volume; tempo,subtempos,grupos e pódio NULL até recoleta.',order="v->>'posicao'")
      for group in ['top10','top100','top5pct','top10pct','top50pct']:
       add(Q('maratonas_'+group),"(v->>'nome_evento')||' · '||to_char((v->>'data_final')::date,'DD/MM')","CASE WHEN v->>'id_evento'='34529' THEN NULL ELSE v->>'tempo_medio' END","CASE WHEN v->>'id_evento'='34529' THEN NULL ELSE v->'incluidos' END","v->'denominador'",'m',"m CROSS JOIN LATERAL jsonb_array_elements(p->'grupos')v",f"v->>'grupo'='{group}'",unit='duracao_hh_mm_ss',note='Média dos menores tempos; até10/100 ou ceil5/10/50% da própria base. Floripa mantida NULL até recoleta.')
      for medal,rank in [('ouro',1),('prata',2),('bronze',3)]:
       add(Q('maratonas_medalhas_'+medal),"(v->>'nome_evento')||' · '||to_char((v->>'data_final')::date,'DD/MM')",f"CASE WHEN v->>'id_evento'='34529' THEN NULL ELSE (SELECT count(*) FROM medalranks r WHERE r.id_evento=v->>'id_evento' AND r.posicao={rank})::text END","NULL::bigint","NULL::bigint",'m',"m,jsonb_array_elements(p->'top10')v",unit='numero',dec=0,note='Pódio parcial:11critérios com mesmo peso;RANK no valor exibido, empates compartilham posição e pulam a seguinte. FloripaNULL atérecoleta.')
